-- Corrige les positions interactives des 16 motifs tactiques fondamentaux.
-- Générée depuis correctedTacticalSteps.ts après validation chess.js.
begin;
with payload(id, starting_fen, steps) as (
values
  ('c2130001-2b00-4e00-9000-000000000001', '8/8/5k2/2r5/8/8/3N4/4K3 w - - 0 1', $$[{"from":"d2","to":"e4","san":"Ne4+","answer_fr":"Attaquez le roi et la tour avec le même cavalier.","answer_en":"Attack the king and the rook with the same knight.","idea_fr":"Le cavalier e4 donne échec au roi f6 et attaque la tour c5.","idea_en":"The knight on e4 checks the king on f6 and attacks the rook on c5."},{"from":"c3","to":"d5","san":"Nd5+","answer_fr":"Créez une double attaque sur le roi et la tour.","answer_en":"Create a double attack on the king and rook.","idea_fr":"Depuis d5, le cavalier attaque e7 et c7.","idea_en":"From d5, the knight attacks e7 and c7."},{"from":"c3","to":"d5","san":"Nd5+","answer_fr":"Donnez échec tout en visant une seconde cible.","answer_en":"Give check while targeting a second piece.","idea_fr":"L’échec donne le tempo pour exploiter la seconde attaque.","idea_en":"The check gives time to exploit the second attack."}]$$::jsonb),
  ('c2130002-2b00-4e00-9000-000000000002', 'q3k3/8/8/1N6/8/8/8/4K3 w - - 0 1', $$[{"from":"b5","to":"c7","san":"Nc7+","answer_fr":"Fourchez le roi et la dame.","answer_en":"Fork the king and queen.","idea_fr":"Le cavalier c7 attaque e8 et a8 ; le roi doit répondre avant la dame.","idea_en":"The knight on c7 attacks e8 and a8; the king must answer before the queen."},{"from":"c2","to":"d4","san":"Nd4+","answer_fr":"Placez le cavalier sur une case qui gagne une cible.","answer_en":"Place the knight on a square that wins a target.","idea_fr":"La fourchette se juge sur les attaques de la case d’arrivée.","idea_en":"The fork is judged by the attacks from the destination square."},{"from":"c3","to":"d5","san":"Nd5+","answer_fr":"Cherchez la fourchette avec échec.","answer_en":"Look for the checking fork.","idea_fr":"Après la fuite du roi, la seconde cible reste attaquée.","idea_en":"After the king moves, the second target remains attacked."}]$$::jsonb),
  ('c2130003-2b00-4e00-9000-000000000003', '4k3/4n3/8/8/8/8/8/4R1K1 w - - 0 1', $$[{"from":"e1","to":"e7","san":"Rxe7+","answer_fr":"Exploitez le cavalier cloué devant le roi.","answer_en":"Exploit the knight pinned in front of the king.","idea_fr":"La tour capture la pièce qui ne pouvait pas quitter la ligne du roi.","idea_en":"The rook captures the piece that could not leave the king’s line."},{"from":"d1","to":"d7","san":"Rxd7+","answer_fr":"Ajoutez une pression sur la pièce clouée.","answer_en":"Add pressure to the pinned piece.","idea_fr":"Le roi d8 se trouve derrière le cavalier d7.","idea_en":"The king on d8 stands behind the knight on d7."},{"from":"e1","to":"e7","san":"Rxe7","answer_fr":"Exploitez un clouage relatif.","answer_en":"Exploit a relative pin.","idea_fr":"Le déplacement du cavalier abandonnerait la dame e8.","idea_en":"Moving the knight would expose the queen on e8."}]$$::jsonb),
  ('c2130004-2b00-4e00-9000-000000000004', '8/7r/6k1/8/8/8/8/3QK3 w - - 0 1', $$[{"from":"d1","to":"h5","san":"Qh5+","answer_fr":"Enfilez le roi et la tour.","answer_en":"Skewer the king and rook.","idea_fr":"La dame h5 attaque le roi g6 puis la tour h7 derrière lui.","idea_en":"The queen on h5 attacks the king on g6 and the rook behind it on h7."},{"from":"d1","to":"h5","san":"Qh5+","answer_fr":"Enfilez le roi et la dame","answer_en":"Skewer the king and queen.","idea_fr":"Le premier échec force le roi à bouger et découvre la dame h7.","idea_en":"The first check forces the king to move and exposes the queen on h7."},{"from":"a1","to":"a5","san":"Ra5+","answer_fr":"Utilisez la rangée ouverte pour une enfilade.","answer_en":"Use the open rank for a skewer.","idea_fr":"La tour a5 donne échec au roi e5 et attaque la tour h5.","idea_en":"The rook on a5 checks the king on e5 and attacks the rook on h5."}]$$::jsonb),
  ('c2130005-2b00-4e00-9000-000000000005', 'q6k/8/8/8/8/8/B7/R3K3 w - - 0 1', $$[{"from":"a2","to":"b3","san":"Bb3","answer_fr":"Déplacez le fou pour découvrir la tour.","answer_en":"Move the bishop to reveal the rook.","idea_fr":"Le départ du fou ouvre la colonne a vers la dame noire a8.","idea_en":"The bishop’s departure opens the a-file toward the black queen on a8."},{"from":"d2","to":"c4","san":"Nc4","answer_fr":"Ouvrez la ligne de la tour vers la dame.","answer_en":"Open the rook’s line toward the queen.","idea_fr":"Le cavalier quitte d2 et la tour d1 attaque la dame d8.","idea_en":"The knight leaves d2 and the rook on d1 attacks the queen on d8."},{"from":"d2","to":"f3","san":"Nf3","answer_fr":"Révélez l’attaque du fou sur la diagonale.","answer_en":"Reveal the bishop’s diagonal attack.","idea_fr":"Le fou c1 vise h6 dès que d2 est libérée.","idea_en":"The bishop on c1 targets h6 once d2 is cleared."}]$$::jsonb),
  ('c2130006-2b00-4e00-9000-000000000006', 'k7/8/8/8/8/8/B7/R3K3 w - - 0 1', $$[{"from":"a2","to":"b3","san":"Bb3+","answer_fr":"Libérez l’échec de la tour.","answer_en":"Release the rook’s check.","idea_fr":"Le fou quitte a2 et la tour a1 donne échec au roi a8.","idea_en":"The bishop leaves a2 and the rook a1 checks the king a8."},{"from":"d2","to":"c4","san":"Nc4+","answer_fr":"Révélez l’échec sur la colonne d.","answer_en":"Reveal the check on the d-file.","idea_fr":"La tour d1 devient l’attaquante du roi d8.","idea_en":"The rook d1 becomes the attacker of the king d8."},{"from":"h2","to":"g3","san":"Bhg3+","answer_fr":"Donnez un échec à la découverte.","answer_en":"Give a discovered check.","idea_fr":"Le fou g3 libère la tour h1 qui attaque le roi h8.","idea_en":"The bishop on g3 reveals the rook h1 attacking the king h8."}]$$::jsonb),
  ('c2130007-2b00-4e00-9000-000000000007', '4k3/8/8/8/8/8/4B3/4R1K1 w - - 0 1', $$[{"from":"e2","to":"b5","san":"Bb5+","answer_fr":"Donnez échec avec le fou et la tour.","answer_en":"Give check with the bishop and rook.","idea_fr":"Le fou b5 attaque e8 tandis que la tour e1 devient visible.","idea_en":"The bishop b5 attacks e8 while the rook e1 becomes visible."},{"from":"d2","to":"a5","san":"Ba5+","answer_fr":"Ouvrez la colonne et donnez un second échec.","answer_en":"Open the file and give a second check.","idea_fr":"Le fou a5 attaque d8 et la tour d1 attaque le roi sur la colonne.","idea_en":"The bishop a5 attacks d8 and the rook d1 attacks the king along the file."},{"from":"h2","to":"e5","san":"Be5+","answer_fr":"Trouvez le double échec de batterie.","answer_en":"Find the battery double check.","idea_fr":"Le fou g3 libère la tour h1 et révèle le second échec.","idea_en":"The bishop g3 clears the h-file and the rook h1 reveals the second check."}]$$::jsonb),
  ('c2130008-2b00-4e00-9000-000000000008', '4k3/3r4/8/8/8/8/3Q4/4K3 w - - 0 1', $$[{"from":"d2","to":"d7","san":"Qxd7+","answer_fr":"Détournez le défenseur par un échec.","answer_en":"Deflect the defender with check.","idea_fr":"La prise force le roi à répondre et change la mission de la pièce qui défendait la septième rangée.","idea_en":"The capture forces a reply and changes the duty of the piece defending the seventh rank."},{"from":"d2","to":"d7","san":"Qxd7+","answer_fr":"Forcez la pièce principale à quitter sa défense.","answer_en":"Force the key piece away from its defense.","idea_fr":"Après la prise en d7, la reine h7 devient accessible sur la septième rangée.","idea_en":"After the capture on d7, the queen h7 becomes accessible along the seventh rank."},{"from":"d3","to":"d7","san":"Qxd7+","answer_fr":"Détournez la tour de la ligne qu’elle protège.","answer_en":"Deflect the rook from the line it protects.","idea_fr":"L’échec impose une réponse avant le gain de la seconde cible.","idea_en":"The check forces a reply before the second target is won."}]$$::jsonb),
  ('c2130009-2b00-4e00-9000-000000000009', '6k1/8/8/8/8/3Q4/8/4K3 w - - 0 1', $$[{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Attirez le roi sur une case vulnérable.","answer_en":"Lure the king onto a vulnerable square.","idea_fr":"La dame h7 offre une cible au roi g8 ; la case d’arrivée doit être calculée.","idea_en":"The queen on h7 offers a target to the king g8; the destination must be calculated."},{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Forcez le roi à choisir sa case de réponse.","answer_en":"Force the king to choose its reply square.","idea_fr":"L’attraction fonctionne lorsque la case proposée modifie les défenses du roi.","idea_en":"The decoy works when the offered square changes the king’s defenses."},{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Attirez la cible vers une ligne de prise.","answer_en":"Lure the target onto a capture line.","idea_fr":"Avant de sacrifier, vérifiez la pièce qui exploitera la case attirée.","idea_en":"Before sacrificing, check which piece will exploit the decoy square."}]$$::jsonb),
  ('c2130010-2b00-4e00-9000-000000000010', '4k3/3r4/8/8/8/3Q4/8/4R2K w - - 0 1', $$[{"from":"d3","to":"d7","san":"Qxd7+","answer_fr":"Exploitez une tour qui doit remplir deux missions.","answer_en":"Exploit a rook with two duties.","idea_fr":"La tour d7 ne peut pas protéger simultanément la ligne et la cible qu’elle garde.","idea_en":"The rook on d7 cannot protect both the line and the target it guards."},{"from":"d3","to":"d7","san":"Qxd7+","answer_fr":"Ajoutez une seconde obligation au défenseur.","answer_en":"Add a second duty to the defender.","idea_fr":"La prise avec échec transforme la surcharge en gain concret.","idea_en":"The checking capture turns the overload into a concrete gain."},{"from":"d3","to":"d7","san":"Qxd7+","answer_fr":"Calculez quelle mission le défenseur abandonne.","answer_en":"Calculate which duty the defender abandons.","idea_fr":"Une surcharge n’existe que si les deux missions sont réellement incompatibles.","idea_en":"An overload exists only when the two duties are genuinely incompatible."}]$$::jsonb),
  ('c2130011-2b00-4e00-9000-000000000011', '4k3/8/8/8/8/3r4/2B5/4K3 w - - 0 1', $$[{"from":"c2","to":"d3","san":"Bxd3","answer_fr":"Supprimez le défenseur de la ligne.","answer_en":"Remove the defender from the line.","idea_fr":"Le fou se place pour attaquer la tour d7 qui protège la cible.","idea_en":"The bishop places itself to attack the rook d7 protecting the target."},{"from":"e2","to":"e7","san":"Qxe7+","answer_fr":"Éliminez la pièce qui protège le roi.","answer_en":"Remove the piece protecting the king.","idea_fr":"La prise de la tour e7 ouvre la ligne vers le roi e8.","idea_en":"Capturing the rook e7 opens the line toward the king e8."},{"from":"d2","to":"d7","san":"Qxd7+","answer_fr":"Retirez le défenseur avant de prendre la cible.","answer_en":"Remove the defender before taking the target.","idea_fr":"La pièce défensive est la première cible concrète de la combinaison.","idea_en":"The defensive piece is the combination’s first concrete target."}]$$::jsonb),
  ('c2130012-2b00-4e00-9000-000000000012', 'k7/8/8/8/8/8/2B5/R3K3 w - - 0 1', $$[{"from":"c2","to":"a4","san":"Ba4","answer_fr":"Coupez la ligne entre la tour et sa cible.","answer_en":"Cut the line between the rook and its target.","idea_fr":"Le fou a4 interrompt la colonne a entre la tour noire et la tour blanche.","idea_en":"The bishop a4 interrupts the a-file between the black and white rooks."},{"from":"d5","to":"c6","san":"Bc6","answer_fr":"Placez un obstacle sur la diagonale.","answer_en":"Place an obstacle on the diagonal.","idea_fr":"Le fou c6 coupe la diagonale a8–h1 de la dame noire.","idea_en":"The bishop c6 cuts the black queen’s a8–h1 diagonal."},{"from":"e2","to":"a6","san":"Ba6","answer_fr":"Interrompez la communication adverse.","answer_en":"Interrupt the opponent’s communication.","idea_fr":"La pièce intermédiaire prive la tour h8 de sa ligne vers la tour a1.","idea_en":"The intermediate piece denies the rook h8 its line toward the rook a1."}]$$::jsonb),
  ('c2130013-2b00-4e00-9000-000000000013', 'k7/8/8/r7/8/8/8/R3K3 w - - 0 1', $$[{"from":"a1","to":"a5","san":"Rxa5+","answer_fr":"Exploitez la pression à travers la tour noire.","answer_en":"Exploit the pressure through the black rook.","idea_fr":"La tour blanche capture la pièce intermédiaire et donne échec au roi a8.","idea_en":"The white rook captures the intermediate piece and checks the king a8."},{"from":"b1","to":"e4","san":"Bxe4+","answer_fr":"Utilisez la diagonale qui traversait la pièce.","answer_en":"Use the diagonal that ran through the piece.","idea_fr":"Le fou capture e4 et la ligne vers le roi h6 devient active.","idea_en":"The bishop captures e4 and the line toward the king h6 becomes active."},{"from":"d1","to":"d7","san":"Qxd7+","answer_fr":"Transformez la pression indirecte en prise.","answer_en":"Turn indirect pressure into a capture.","idea_fr":"La dame traverse la colonne jusqu’à la tour d7 puis attaque le roi d8.","idea_en":"The queen crosses the file to capture the rook d7 and checks the king d8."}]$$::jsonb),
  ('c2130014-2b00-4e00-9000-000000000014', '6k1/8/8/8/8/3Q4/8/4K3 w - - 0 1', $$[{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Donnez la dame pour ouvrir l’attaque contre le roi.","answer_en":"Give the queen to open the attack on the king.","idea_fr":"Le sacrifice doit être évalué par la suite forcing et non par la première prise.","idea_en":"The sacrifice must be evaluated by the forcing continuation, not the first capture."},{"from":"d1","to":"h5","san":"Qh5+","answer_fr":"Sacrifiez du matériel pour gagner des temps.","answer_en":"Sacrifice material to gain tempi.","idea_fr":"L’échec ouvre les lignes et donne la priorité à l’initiative.","idea_en":"The check opens lines and gives priority to the initiative."},{"from":"d2","to":"d8","san":"Qd8+","answer_fr":"Mesurez la compensation avant de sacrifier.","answer_en":"Measure the compensation before sacrificing.","idea_fr":"Un sacrifice correct doit produire une compensation vérifiable.","idea_en":"A sound sacrifice must produce verifiable compensation."}]$$::jsonb),
  ('c2130015-2b00-4e00-9000-000000000015', '6k1/3r4/8/8/8/3Q4/2B5/3R2K1 w - - 0 1', $$[{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Jouez le coup forcing avant de reprendre la tour.","answer_en":"Play the forcing move before recapturing the rook.","idea_fr":"La prise en d7 peut attendre ; l’échec h7 impose d’abord une réponse.","idea_en":"The capture on d7 can wait; the check on h7 must be answered first."},{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Insérez un échec avant la reprise.","answer_en":"Insert a check before recapturing.","idea_fr":"Le coup intermédiaire change l’ordre des coups et gagne un tempo.","idea_en":"The zwischenzug changes the move order and gains a tempo."},{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Ne reprenez pas automatiquement.","answer_en":"Do not recapture automatically.","idea_fr":"Cherchez d’abord l’échec, la prise ou la menace la plus forcing.","idea_en":"First search for the most forcing check, capture or threat."}]$$::jsonb),
  ('c2130016-2b00-4e00-9000-000000000016', '6k1/3r4/8/8/8/3Q4/2B5/4K3 w - - 0 1', $$[{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Répondez à la menace sur la dame par une contre-attaque.","answer_en":"Answer the threat against the queen with a counterattack.","idea_fr":"La tour d7 attaque la dame d3 ; l’échec h7 crée une menace plus urgente.","idea_en":"The rook d7 attacks the queen d3; the check on h7 creates a more urgent threat."},{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Créez une menace plus forte que celle reçue.","answer_en":"Create a stronger threat than the one received.","idea_fr":"La dame quitte l’attaque de la tour et donne un échec immédiat.","idea_en":"The queen leaves the rook’s attack and gives immediate check."},{"from":"d3","to":"h7","san":"Qh7+","answer_fr":"Défendez-vous activement par un échec.","answer_en":"Defend actively with a check.","idea_fr":"Une contre-attaque réussie force l’adversaire à changer de priorité.","idea_en":"A successful counterattack forces the opponent to change priorities."}]$$::jsonb)
)
update public.lessons as lesson
set starting_fen = payload.starting_fen,
    steps = payload.steps,
    updated_at = now()
from payload
where lesson.id = payload.id::uuid;
commit;
